#!/usr/bin/env bash
# Writes the benchmark workloads to bench/sql/ (speedtest1-style; sqlite's test/speedtest1.c is the model). The SQL is
# generated by the real sqlite3 from an LCG, so every run of every engine reads the same bytes.
set -euo pipefail
cd "$(dirname "$0")"
mkdir -p sql
N=${N:-100000}
# a random row source: n, x (an LCG), and a text column
rows() { # $1 = row count, $2 = SELECT over (n, x)
  sqlite3 :memory: "WITH RECURSIVE r(n, x) AS (SELECT 1, 12345 UNION ALL SELECT n+1, (x*1103515245+12345) % 2147483648 FROM r WHERE n < $1) $2"
}
words="'alpha','bravo','charlie','delta','echo','foxtrot','golf','hotel','india','juliet','kilo','lima','mike','november','oscar','papa'"
# the setup the query workloads share: a table filled by INSERT ... SELECT (little parsing)
setup() {
  cat <<EOF
CREATE TABLE t1(a INTEGER PRIMARY KEY, b INTEGER, c TEXT, d REAL);
WITH RECURSIVE r(n, x) AS (SELECT 1, 12345 UNION ALL SELECT n+1, (x*1103515245+12345) % 2147483648 FROM r WHERE n < $N)
INSERT INTO t1 SELECT n, x % 100000, 'row ' || n || ' ' || (x % 997), (x % 10000) / 7.0 FROM r;
EOF
}

# 1. INSERT statements, one row each, in one transaction (parsing and b-tree inserts)
{ echo "BEGIN;"; echo "CREATE TABLE t1(a INTEGER, b INTEGER, c TEXT);"
  rows $N "SELECT 'INSERT INTO t1 VALUES(' || n || ',' || (x % 1000000) || ',''' || 'row ' || n || ' value ' || (x % 9973) || ''');' FROM r"
  echo "COMMIT;"; echo "SELECT count(*), sum(b), max(length(c)) FROM t1;"; } > sql/insert.sql

# 2. INSERT into an indexed table in random key order
{ echo "BEGIN;"; echo "CREATE TABLE t2(a INTEGER PRIMARY KEY, b INTEGER, c TEXT);"; echo "CREATE INDEX t2b ON t2(b);"
  rows $N "SELECT 'INSERT INTO t2 VALUES(' || ((n * 7919) % 10000019) || ',' || (x % 100000) || ',''' || 'v' || (x % 9973) || ''');' FROM r"
  echo "COMMIT;"; echo "SELECT count(*), min(a), max(a), sum(b) FROM t2;"; } > sql/insert-indexed.sql

# 3. full scans with WHERE and aggregates
{ setup
  rows 50 "SELECT 'SELECT count(*), avg(b), sum(length(c)) FROM t1 WHERE b BETWEEN ' || (x % 90000) || ' AND ' || (x % 90000 + 1000) || ';' FROM r"
  rows 20 "SELECT 'SELECT count(*) FROM t1 WHERE c LIKE ''%' || (x % 997) || '%'';' FROM r"; } > sql/scan.sql

# 4. point lookups through an index and by rowid
{ setup; echo "CREATE INDEX t1b ON t1(b);"
  rows 20000 "SELECT 'SELECT a, c FROM t1 WHERE b = ' || (x % 100000) || ';' FROM r"
  rows 20000 "SELECT 'SELECT b, d FROM t1 WHERE a = ' || (x % $N + 1) || ';' FROM r"; } > sql/lookup.sql

# 5. ORDER BY, GROUP BY, DISTINCT
{ setup
  echo "SELECT a, b, c FROM t1 ORDER BY c LIMIT 10;"
  echo "SELECT b % 100 AS k, count(*), sum(d), min(c), max(c) FROM t1 GROUP BY k ORDER BY k;"
  echo "SELECT count(DISTINCT b) FROM t1;"
  echo "SELECT b, count(*) FROM t1 GROUP BY b HAVING count(*) > 3 ORDER BY 2 DESC, 1 LIMIT 20;"
  echo "SELECT * FROM t1 ORDER BY d DESC, a LIMIT 5;"; } > sql/sort.sql

# 6. UPDATE and DELETE
{ setup; echo "CREATE INDEX t1b ON t1(b);"; echo "BEGIN;"
  rows 20000 "SELECT 'UPDATE t1 SET b = b + 1, c = ''u' || n || ''' WHERE a = ' || (x % $N + 1) || ';' FROM r"
  rows 2000 "SELECT 'DELETE FROM t1 WHERE a = ' || (x % $N + 1) || ';' FROM r"
  echo "UPDATE t1 SET d = d * 2 WHERE b < 5000;"
  echo "DELETE FROM t1 WHERE b BETWEEN 50000 AND 60000;"
  echo "COMMIT;"; echo "SELECT count(*), sum(b), sum(d), max(c) FROM t1;"; } > sql/update.sql

# 7. joins through an index
{ setup
  echo "CREATE TABLE t3(k INTEGER PRIMARY KEY, name TEXT, grp INTEGER);"
  echo "WITH RECURSIVE r(n) AS (SELECT 0 UNION ALL SELECT n+1 FROM r WHERE n < 999) INSERT INTO t3 SELECT n, 'name' || n, n % 10 FROM r;"
  echo "SELECT t3.grp, count(*), sum(t1.d) FROM t1 JOIN t3 ON t3.k = t1.b % 1000 GROUP BY t3.grp ORDER BY 1;"
  echo "CREATE INDEX t1b ON t1(b);"
  rows 200 "SELECT 'SELECT count(*), max(t1.c) FROM t3 JOIN t1 ON t1.b = t3.k * 100 + ' || (x % 100) || ' WHERE t3.grp = ' || (x % 10) || ';' FROM r"; } > sql/join.sql

# 8. the INSERT workload into a database file (lean-sqlite writes the changed pages' file at COMMIT)
# (this sqlite3 build refuses journal_mode=OFF, so sqlite3 keeps its rollback journal, without fsync)
{ echo "PRAGMA synchronous=OFF;"; cat sql/insert.sql; } > sql/file-insert.sql
ls -la sql
